 const end1=isoAdd(adm,d1-1),end2=d2?isoAdd(end1,d2):null,last=end2||end1,left=daysBetween(t,last),r={d1,d2,adm,end1,end2,last,left,total:d1+(d2||0),prorStart:end2?isoAdd(end1,1):null};
